import {myFormations,publicFormations,readFormation,manageFormation,likeFormation} from './formation-api.mjs';
import {cleanDraft} from './drafter-model-v2.mjs';
import {drawFormation} from './drafter-share-render.mjs';
const $=id=>document.getElementById(id),el=(tag,text,cls)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n};let mine=new URL(location.href).searchParams.get('view')==='mine',records=[],known=new Map(),generation=0;
const dialog=el('dialog',undefined,'formation-image-dialog'),heading=el('h2','Formation'),preview=el('canvas'),actions=el('div',undefined,'modal-actions');dialog.setAttribute('aria-label','Formation image');dialog.append(heading,preview,actions);document.body.append(dialog);
const warning=el('dialog',undefined,'formation-warning-dialog'),warningTitle=el('h2','Unable to complete action'),warningMessage=el('p'),warningActions=el('div',undefined,'modal-actions'),warningClose=el('button','Close','btn');warningTitle.id='formation-warning-title';warningMessage.id='formation-warning-message';warning.setAttribute('aria-labelledby',warningTitle.id);warning.setAttribute('aria-describedby',warningMessage.id);warningClose.type='button';warningClose.onclick=()=>warning.close();warningActions.append(warningClose);warning.append(warningTitle,warningMessage,warningActions);document.body.append(warning);
function showWarning(error){const message=error?.message||'';warningMessage.textContent=/permission denied|sign in|authenticated|jwt|unauthorized/i.test(message)?'Your current session cannot perform this action. Please sign in and try again.':/fetch|network|offline/i.test(message)?'Could not connect. Check your connection and try again.':'Something went wrong. Please try again.';if(!warning.open)warning.showModal()}
const shareUrl=id=>{const url=new URL(location.href);url.search='';url.hash='f='+encodeURIComponent(id);return url.href};
const openUrl=record=>'/drafter/horde.html?formation='+encodeURIComponent(record.id)+(mine?'&private=1':'');
async function picture(canvas,record){const draft=cleanDraft(record.payload,known);await drawFormation({canvas,draft,known,summaries:[],title:record.name,author:draft.shareAuthor,notes:draft.shareNotes,theme:'light',everything:false})}
async function inspect(record){heading.textContent=record.name;actions.replaceChildren();const open=el('a',mine?'Edit draft':'Open as draft','btn');open.href=openUrl(record);actions.append(open);for(const [label,callback] of [['Copy link',()=>navigator.clipboard.writeText(shareUrl(record.id))],['Download PNG',async()=>{const blob=await new Promise(resolve=>preview.toBlob(resolve,'image/png'));const url=URL.createObjectURL(blob),a=el('a');a.href=url;a.download=record.name.replace(/[^a-z0-9_-]/gi,'-')+'.png';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}],['Close',()=>dialog.close()]]){const b=el('button',label,'btn secondary');b.onclick=async()=>{try{await callback()}catch(error){showWarning(error)}};actions.append(b)}dialog.showModal();try{await picture(preview,record)}catch(error){dialog.close();showWarning(error)}}
async function load(){const token=++generation;$('mine-view').setAttribute('aria-pressed',String(mine));$('public-view').setAttribute('aria-pressed',String(!mine));$('library-status').textContent='Loading formations…';try{const loaded=mine?await myFormations():await publicFormations();if(token!==generation)return;records=loaded;render();$('library-status').textContent=records.length+' formations.'}catch(error){if(token!==generation)return;records=[];render();$('library-status').textContent='Could not load formations.';showWarning(error)}}
const observer=new IntersectionObserver(entries=>{for(const entry of entries)if(entry.isIntersecting){observer.unobserve(entry.target);entry.target.renderImage?.()}},{rootMargin:'200px'});
function render(){observer.disconnect();const shown=records.filter(r=>(!$('library-mode').value||r.payload.gameMode===$('library-mode').value)&&(!$('library-search').value||(r.name+' '+(r.payload.shareAuthor||'')).toLowerCase().includes($('library-search').value.toLowerCase())));if($('library-sort').value==='likes')shown.sort((a,b)=>(b.likes||0)-(a.likes||0));const list=$('formation-list');list.replaceChildren();if(!shown.length){list.append(el('div',mine?'Your saved formations will appear here.':'Published formations will appear here.','library-empty'));return}for(const record of shown){const card=el('article',undefined,'formation-entry'),imageButton=el('button',undefined,'formation-image-button'),canvas=el('canvas');imageButton.setAttribute('aria-label','View '+record.name);imageButton.append(canvas);imageButton.onclick=()=>inspect(record);imageButton.renderImage=()=>picture(canvas,record).catch(error=>{showWarning(error)});observer.observe(imageButton);card.append(imageButton,el('h2',record.name),el('p',record.payload.gameMode+' · '+record.payload.mode,'caption'));if(record.payload.shareAuthor)card.append(el('p','By '+record.payload.shareAuthor,'caption'));if(record.payload.shareNotes)card.append(el('p',record.payload.shareNotes,'formation-card-note'));const row=el('div',undefined,'row');if(!mine){const like=el('button','Like '+(record.likes||0),'btn secondary');like.setAttribute('aria-pressed',String(!!record.liked));like.onclick=async()=>{like.disabled=true;try{const result=await likeFormation(record.id);record.likes=result.likes;record.liked=result.liked;like.textContent='Like '+result.likes;like.setAttribute('aria-pressed',String(result.liked))}catch(error){showWarning(error)}finally{like.disabled=false}};row.append(like)}else card.append(el('span',record.published?'Private draft + published snapshot':'Private draft','badge'));const open=el('a',mine?'Edit draft':'Open','btn secondary');open.href=openUrl(record);row.append(open);if(mine){if(record.published){const unpublish=el('button','Unpublish','btn secondary');unpublish.onclick=()=>manage(record,'unpublish');row.append(unpublish)}const remove=el('button','Delete','btn secondary');remove.onclick=()=>manage(record,'delete');row.append(remove)}card.append(row);list.append(card)}}
async function manage(record,action){if(!confirm(action==='delete'?'Delete this formation and its public version?':'Unpublish this formation? Your private draft remains.'))return;try{await manageFormation(record.id,record.revision,action);await load()}catch(error){showWarning(error)}}
$('mine-view').onclick=()=>{mine=true;load()};$('public-view').onclick=()=>{mine=false;load()};$('refresh-library').onclick=load;$('library-mode').onchange=render;$('library-search').oninput=render;$('library-sort').onchange=render;
try{const data=await(await fetch('/drafter-roster.json')).json();known=new Map(data.entries.map(e=>[e.key,e]));await load();const id=location.hash.startsWith('#f=')?decodeURIComponent(location.hash.slice(3)):null;if(id){mine=false;await inspect(await readFormation(id,false))}}catch(error){showWarning(error)}
